def get_car_route(car_id, chosen_routes):
    """Return the selected route including the vehicle's depot connections."""
    chosen = chosen_routes.get(car_id)
    if not chosen or chosen == "inactive" or chosen not in route:
        return []
    base = route[chosen]
    prefix = Depot_exit_route.get(car_id, [])
    suffix = Depot_route.get(car_id, [])
    return [base[0]] + prefix + base[1:] + suffix
